```sql
create schema private;

grant usage on schema private to authenticated;

create function private.is_friend(p_user_id uuid) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.friendships
    where (requester_id = p_user_id and addressee_id = auth.uid())
       or (requester_id = auth.uid() and addressee_id = p_user_id)
       and status = 'accepted'
  );
$$;

create function private.can_delete_friendship(p_requester_id uuid, p_addressee_id uuid) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.friendships
    where (requester_id = p_requester_id and addressee_id = p_addressee_id)
       or (requester_id = p_addressee_id and addressee_id = p_requester_id)
  );
$$;

alter table public.friendships enable row level security;
alter table public.posts enable row level security;

create policy "posts_select"
  on public.posts
  for select
  to anon, authenticated
  using (
    audience = 'public'
    or (auth.uid() = author_id)
    or (audience = 'friends' and private.is_friend(author_id))
  );

create policy "posts_insert"
  on public.posts
  for insert
  to authenticated
  with check (auth.uid() = author_id and audience in ('public', 'friends', 'only_me'));

create policy "posts_update"
  on public.posts
  for update
  to authenticated
  using (auth.uid() = author_id)
  with check (auth.uid() = author_id and audience in ('public', 'friends', 'only_me'));

create policy "posts_delete"
  on public.posts
  for delete
  to authenticated
  using (auth.uid() = author_id);

create policy "friendships_select"
  on public.friendships
  for select
  to authenticated
  using (
    requester_id = auth.uid()
    or addressee_id = auth.uid()
  );

create policy "friendships_insert"
  on public.friendships
  for insert
  to authenticated
  with check (
    requester_id = auth.uid()
    and addressee_id <> auth.uid()
    and status = 'pending'
  );

create policy "friendships_update"
  on public.friendships
  for update
  to authenticated
  using (
    addressee_id = auth.uid()
    and requester_id <> auth.uid()
    and status = 'pending'
  )
  with check (
    addressee_id = auth.uid()
    and requester_id <> auth.uid()
    and status = 'accepted'
  );

create policy "friendships_delete"
  on public.friendships
  for delete
  to authenticated
  using (
    private.can_delete_friendship(requester_id, addressee_id)
  );
```

