create function private.is_org_admin() returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.org_admins o where o.user_id = auth.uid())
$$;

alter table public.org_admins enable row level security;
alter table public.files enable row level security;

create policy org_admins_select on public.org_admins
  for select to authenticated
  using (true);

create policy files_select on public.files
  for select to authenticated
  using (owner_id = auth.uid() or private.is_org_admin());

create policy files_insert on public.files
  for insert to authenticated
  with check (owner_id = auth.uid() and not legal_hold);

create policy files_update on public.files
  for update to authenticated
  using (owner_id = auth.uid() or private.is_org_admin())
  with check (
    (owner_id = auth.uid() or private.is_org_admin())
    and (not legal_hold or (legal_hold and private.is_org_admin()))
  );

create policy files_delete on public.files
  for delete to authenticated
  using (owner_id = auth.uid() or (private.is_org_admin() and not legal_hold));
```

