language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.building_staff s where s.building_id = p_building_id and s.user_id = auth.uid())
$$;

create function private.can_see_unit(p_unit_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.units u
    join public.residents r on r.unit_id = u.id
    where u.id = p_unit_id and r.user_id = auth.uid()
  ) or exists (
    select 1 from public.units u
    join public.building_staff s on s.building_id = u.building_id
    where u.id = p_unit_id and s.user_id = auth.uid()
  )
$$;

