    join public.building_staff s on s.building_id = u.building_id
    where u.id = p_unit_id and s.user_id = auth.uid()
  )
$$;

create function private.can_update_request_status(p_request_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (
    select 1 from public.requests r
    join public.building_staff s on s.building_id = (select u.building_id from public.units u where u.id = r.unit_id)
    where r.id = p_request_id and s.user_id = auth.uid()
  )
$$;

alter table public.units enable row level security;
alter table public.residents enable row level security;
alter table public.building_staff enable row level security;
alter table public.requests enable row level security;
alter table public.request_photos enable row level security;

