  for select to authenticated
  using (private.can_see_unit(id));

create policy "residents_select_own" on public.residents
  for select to authenticated
  using (user_id = auth.uid());

create policy "building_staff_select_own" on public.building_staff
  for select to authenticated
  using (user_id = auth.uid());

create policy "requests_select_visible" on public.requests
  for select to authenticated
  using (private.can_see_unit(unit_id));

create policy "request_photos_select_visible" on public.request_photos
  for select to authenticated
  using (private.can_see_unit(request_id));

create policy "requests_insert_resident_own_unit" on public.requests
  for insert to authenticated
  with check (created_by = auth.uid() and private.is_resident(unit_id) and status = 'open');

