  for insert to authenticated
  with check (private.can_see_unit(request_id));

create policy "requests_update_staff_status" on public.requests
  for update to authenticated
  using (private.can_update_request_status(id))
  with check (private.can_update_request_status(id));

create function public.prevent_request_non_status_update() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if new.id is distinct from old.id
     or new.unit_id is distinct from old.unit_id
     or new.created_by is distinct from old.created_by
     or new.description is distinct from old.description then
    raise exception 'Only status can be updated on requests';
  end if;
  return new;
end
$$;

create trigger prevent_request_non_status_update_trigger
  before update on public.requests
  for each row execute function public.prevent_request_non_status_update();

revoke all on public.units from anon, authenticated;
revoke all on public.residents from anon, authenticated;
revoke all on public.building_staff from anon, authenticated;
revoke all on public.requests from anon, authenticated;
revoke all on public.request_photos from anon, authenticated;

grant select on public.units to authenticated;
grant select on public.residents to authenticated;
grant select on public.building_staff to authenticated;
grant select, insert, update on public.requests to authenticated;
grant select, insert on public.request_photos to authenticated;

grant all on public.units to service_role;
