```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

create policy "Authenticated users can view all auctions"
  on public.auctions
  for select
  to authenticated
  using (true);

create policy "Sellers can view all bids"
  on public.bids
  for select
  to authenticated
  using (exists (select 1 from public.auctions where auctions.id = bids.auction_id and auctions.seller_id = auth.uid()));

create policy "Users can view their own bids"
  on public.bids
  for select
  to authenticated
  using (bidder_id = auth.uid());

create function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_auction public.auctions%rowtype;
  v_current_highest numeric;
  v_min_increment numeric;
  v_new_highest numeric;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select * into v_auction from public.auctions where id = p_auction_id;

  if not found then
    raise exception 'Auction not found';
  end if;

  if v_auction.ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  if v_auction.seller_id = v_uid then
    raise exception 'Cannot bid on your own auction';
  end if;

  v_min_increment := v_auction.min_increment;
  v_current_highest := v_auction.highest_bid;

  if v_current_highest is null then
    if p_amount <= v_auction.starting_price then
      raise exception 'Bid amount must be above starting price';
    end if;
    v_new_highest := p_amount;
  else
    if p_amount <= v_current_highest + v_min_increment then
      raise exception 'Bid amount must be above current highest bid plus minimum increment';
    end if;
    v_new_highest := p_amount;
  end if;

  perform pg_advisory_xact_lock(hashtext('auction_' || v_auction.id::text));

  update public.auctions
  set highest_bid = v_new_highest,
      highest_bidder = v_uid
  where id = p_auction_id;

  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_uid, p_amount, now());

  return v_new_highest;
end;
$$;

revoke all on public.auctions from anon;
revoke all on public.bids from anon;
revoke all on public.auctions from authenticated;
revoke all on public.bids from authenticated;

grant select on public.auctions to authenticated;
grant select on public.bids to authenticated;
grant usage, select on sequence public.bids_id_seq to authenticated;

grant all on public.auctions to service_role;
grant all on public.bids to service_role;
grant usage, select on sequence public.bids_id_seq to service_role;

grant execute on function public.place_bid(bigint, numeric) to authenticated;
grant execute on function public.place_bid(bigint, numeric) to service_role;
