```sql
alter table public.auctions enable row level security;
alter table public.bids enable row level security;

-- R1: Signed-in users can see every auction
create policy "auctions_select_authenticated"
  on public.auctions
  for select
  to authenticated
  using (true);

-- R1: Bidders can see their own bids; sellers can see every bid on their auctions
create policy "bids_select_authenticated"
  on public.bids
  for select
  to authenticated
  using (
    bidder_id = auth.uid()
    or exists (
      select 1 from public.auctions
      where id = auction_id and seller_id = auth.uid()
    )
  );

-- R2: Nobody can create, change or delete auctions or bids directly
-- No insert/update/delete policies on auctions or bids for authenticated/anon
-- Explicitly deny via no policies + ensure service_role bypasses

-- R5: Anonymous visitors cannot see or change anything
-- No policies for anon role means all denied by default

-- R6: Service role bypasses RLS automatically (Supabase default behavior)

-- R3 & R4: place_bid function
create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_auction_exists boolean;
  v_ends_at timestamptz;
  v_seller_id uuid;
  v_current_highest_bid numeric;
  v_min_increment numeric;
  v_starting_price numeric;
  v_bid_count integer;
begin
  -- Check caller is signed in
  if v_uid is null then
    raise exception 'Authentication required';
  end if;

  -- Check auction exists
  select exists(select 1 from public.auctions where id = p_auction_id)
    into v_auction_exists;

  if not v_auction_exists then
    raise exception 'Auction does not exist';
  end if;

  -- Lock and fetch auction data
  select ends_at, seller_id, highest_bid, min_increment, starting_price, count(*)
    into v_ends_at, v_seller_id, v_current_highest_bid, v_min_increment, v_starting_price, v_bid_count
    from public.auctions
    where id = p_auction_id
    for update;

  -- Check auction has ended
  if v_ends_at <= now() then
    raise exception 'Auction has ended';
  end if;

  -- Check caller is not the seller
  if v_seller_id = v_uid then
    raise exception 'Cannot bid on your own auction';
  end if;

  -- Validate amount
  if p_amount is null or p_amount <= 0 then
    raise exception 'Invalid bid amount';
  end if;

  -- Check minimum bid requirement
  if v_bid_count = 0 then
    -- No bids yet: must meet starting price
    if p_amount < v_starting_price then
      raise exception 'Bid must be at least the starting price';
    end if;
  else
    -- Existing bids: must exceed highest bid by minimum increment
    if p_amount <= coalesce(v_current_highest_bid, 0) + v_min_increment then
      raise exception 'Bid must be at least % above current highest bid', 
        coalesce(v_current_highest_bid, 0) + v_min_increment;
    end if;
  end if;

  -- Record the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_uid, p_amount, now());

  -- Get the new highest bid (will be our bid since we validated it's higher)
  return p_amount;
end;
$$;

