create or replace function public.place_bid(p_auction_id bigint, p_amount numeric)
returns numeric
language plpgsql
security definer set search_path = public
as $$
declare
  v_user_id uuid := auth.uid();
  v_auction_exists boolean;
  v_ended boolean;
  v_seller_id uuid;
  v_starting_price numeric;
  v_min_increment numeric;
  v_ends_at timestamptz;
  v_current_highest_bid numeric;
  v_valid_amount boolean;
begin
  -- Check caller is signed in
  if v_user_id is null then
    raise exception 'Not authenticated';
  end if;

  -- Get auction details
  select exists(select 1 from public.auctions where id = p_auction_id)
    into v_auction_exists;

  if not v_auction_exists then
    raise exception 'Auction does not exist';
  end if;

  select ends_at > now()
    into v_ended
    from public.auctions
    where id = p_auction_id;

  if v_ended is false then
    raise exception 'Auction has ended';
  end if;

  select seller_id, starting_price, min_increment, ends_at, highest_bid
    into v_seller_id, v_starting_price, v_min_increment, v_ends_at, v_current_highest_bid
    from public.auctions
    where id = p_auction_id;

  -- Check caller is not the seller
  if v_seller_id = v_user_id then
    raise exception 'Cannot bid on your own auction';
  end if;

  -- Validate amount
  if p_amount <= 0 then
    raise exception 'Invalid bid amount';
  end if;

  -- Determine if bid is valid
  if v_current_highest_bid is null then
    -- No bids yet: must be at or above starting price
    v_valid_amount := p_amount >= v_starting_price;
  else
    -- Must be above highest bid by at least min_increment
    v_valid_amount := p_amount > v_current_highest_bid + v_min_increment;
  end if;

  if not v_valid_amount then
    raise exception 'Bid amount is too low';
  end if;

  -- Insert the bid
  insert into public.bids (auction_id, bidder_id, amount, placed_at)
  values (p_auction_id, v_user_id, p_amount, now());

  -- Get the new highest bid (should be the one we just inserted)
  select coalesce(max(amount), 0)
    into p_amount
    from public.bids
    where auction_id = p_auction_id;

  -- Update the auction's highest bid and highest_bidder
  update public.auctions
  set highest_bid = p_amount,
      highest_bidder = v_user_id
  where id = p_auction_id;

  return p_amount;
end;
$$;

