create schema private;

grant usage on schema private to authenticated;

create function private.is_instructor(p_class_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select exists (select 1 from public.classes c where c.id = p_class_id and c.instructor_id = auth.uid())
$$;

create function private.can_enroll(p_class_id bigint) returns boolean
language sql stable security definer set search_path = ''
as $$
  select coalesce((select c.capacity - (select count(*)::int from public.class_spots s where s.class_id = p_class_id and s.status = 'enrolled') > 0 from public.classes c where c.id = p_class_id), false)
$$;

alter table public.classes enable row level security;
alter table public.class_spots enable row level security;

create policy classes_select on public.classes
  for select to authenticated
  using (true);

create policy class_spots_select on public.class_spots
  for select to authenticated
  using (user_id = auth.uid() or private.is_instructor(class_id));

create policy class_spots_insert on public.class_spots
  for insert to authenticated
  with check (
    user_id = auth.uid()
    and status in ('enrolled', 'waitlisted')
    and (
      status = 'enrolled' and private.can_enroll(class_id)
      or status = 'waitlisted' and not private.can_enroll(class_id)
    )
  );

create policy class_spots_update on public.class_spots
  for update to authenticated
  using (user_id = auth.uid() and status = 'waitlisted' and private.can_enroll(class_id))
  with check (user_id = auth.uid() and status = 'enrolled');

create policy class_spots_delete on public.class_spots
  for delete to authenticated
  using (user_id = auth.uid() or private.is_instructor(class_id));

create function private.class_spots_guard() returns trigger
language plpgsql security definer set search_path = ''
as $$
begin
  if auth.role() = 'service_role' then
    return new;
  end if;
  if tg_op = 'INSERT' then
    if new.user_id != auth.uid() then
      raise exception 'only your own spots can be created';
    end if;
    return new;
  end if;
  if tg_op = 'UPDATE' then
    if new.class_id != old.class_id or new.user_id != old.user_id then
      raise exception 'class_id and user_id cannot be changed';
    end if;
    if old.user_id != auth.uid() then
      raise exception 'only the owner can update their spot';
    end if;
    if old.status != 'waitlisted' then
      raise exception 'only waitlisted spots can be promoted';
    end if;
    if new.status != 'enrolled' then
      raise exception 'invalid status change';
    end if;
    if not private.can_enroll(old.class_id) then
      raise exception 'no room to enroll';
    end if;
    return new;
  end if;
  if tg_op = 'DELETE' then
    if old.user_id != auth.uid() and not private.is_instructor(old.class_id) then
      raise exception 'only the owner or instructor can delete a spot';
    end if;
    return old;
  end if;
  raise exception 'unknown operation';
end
$$;

create trigger class_spots_guard
  before insert or update or delete on public.class_spots
  for each row execute function private.class_spots_guard();

